using System;
namespace Exercise
{
    public class Player
    {
        private string name;
        private int goals;
        public Player(string name, int goals) { this.name = name; this.goals = goals; }
        public string GetName() { return name; }
        public int GetGoals() { return goals; }
        public override string ToString() { return name + "(" + goals + ")"; }
    }
}

namespace Exercise;

internal class Team
{
    private string name;
    private Player[] players = new Player[11];
    private int count;
    public Team(string name) { this.name = name; }
    public void Add(Player p) { if (count < players.Length) players[count++] = p; }
    public int GetCount() { return count; }
    public override string ToString() { return name + " " + count; }
}

